import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.Boholvbs.js";const p=JSON.parse('{"title":"Slash commands","description":"Every slash command in the prioricode TUI with aliases — app, session, prompt-scope commands, built-in /init and /review, and custom command lookup.","frontmatter":{"title":"Slash commands","description":"Every slash command in the prioricode TUI with aliases — app, session, prompt-scope commands, built-in /init and /review, and custom command lookup."},"headers":[],"relativePath":"reference/slash-commands.md","filePath":"reference/slash-commands.md"}'),s={name:"reference/slash-commands.md"};function a(c,t,i,n,l,m){return d(),o("div",null,[...t[0]||(t[0]=[r('<p>Typed at the start of a prompt line, <code>/name args…</code>. Aliases route through the same autocomplete (<code>/mo</code> finds <code>/models</code> on purpose). Commands are grouped by where they live: app-level (work anywhere), session-level (need a session open), and prompt-level (shape the next message).</p><h2 id="app-level" tabindex="-1">App-level <a class="header-anchor" href="#app-level" aria-label="Permalink to &quot;App-level&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Aliases</th><th>Does</th></tr></thead><tbody><tr><td><code>/sessions</code></td><td><code>/resume</code>, <code>/continue</code></td><td>session picker — resume, pin (<code>ctrl+f</code>), rename (<code>ctrl+r</code>), delete (<code>ctrl+d</code>)</td></tr><tr><td><code>/new</code></td><td><code>/clear</code></td><td>start a fresh session</td></tr><tr><td><code>/models</code></td><td><code>/mo</code></td><td>model picker</td></tr><tr><td><code>/agents</code></td><td>—</td><td>primary-agent picker</td></tr><tr><td><code>/permission</code></td><td><code>/permissions</code></td><td>session permission mode: default / ask-first / always-allow</td></tr><tr><td><code>/variants</code></td><td>—</td><td>model variant picker (hidden when the model has none)</td></tr><tr><td><code>/mcps</code></td><td>—</td><td>toggle MCP servers (space flips entries)</td></tr><tr><td><code>/connect</code></td><td>—</td><td>provider connection list</td></tr><tr><td><code>/org</code></td><td><code>/orgs</code>, <code>/switch-org</code></td><td>switch console org (shown with 2+ orgs)</td></tr><tr><td><code>/workspaces</code></td><td>—</td><td><em>(experimental, flag-gated)</em> manage workspaces</td></tr><tr><td><code>/status</code></td><td>—</td><td>inventory: providers, MCP, LSP, formatters, plugins</td></tr><tr><td><code>/coordination</code></td><td>—</td><td>cross-session roster and inbox</td></tr><tr><td><code>/settings</code></td><td>—</td><td>settings UI (writes <code>tui.json</code>)</td></tr><tr><td><code>/themes</code></td><td>—</td><td>theme picker</td></tr><tr><td><code>/debug</code></td><td>—</td><td>debug info dialog</td></tr><tr><td><code>/help</code></td><td>—</td><td>keybinding help</td></tr><tr><td><code>/exit</code></td><td><code>/quit</code>, <code>/q</code></td><td>leave (also: bare <code>exit</code>, <code>quit</code>, or <code>:q</code> as the whole prompt)</td></tr></tbody></table><h2 id="session-level" tabindex="-1">Session-level <a class="header-anchor" href="#session-level" aria-label="Permalink to &quot;Session-level&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Aliases</th><th>Does</th></tr></thead><tbody><tr><td><code>/share</code></td><td>—</td><td>share/copy link (needs consent once; hidden if <code>share: disabled</code>)</td></tr><tr><td><code>/unshare</code></td><td>—</td><td>delete the share</td></tr><tr><td><code>/rename</code></td><td>—</td><td>retitle the session</td></tr><tr><td><code>/timeline</code></td><td>—</td><td>jump to any message</td></tr><tr><td><code>/fork</code></td><td>—</td><td>fork from a timeline message</td></tr><tr><td><code>/compact</code></td><td><code>/summarize</code></td><td>summarize history now</td></tr><tr><td><code>/undo</code></td><td>—</td><td>revert last user message (+ restore it into the prompt)</td></tr><tr><td><code>/redo</code></td><td>—</td><td>step reverts forward</td></tr><tr><td><code>/timestamps</code></td><td><code>/toggle-timestamps</code></td><td>show/hide message timestamps</td></tr><tr><td><code>/thinking</code></td><td><code>/toggle-thinking</code></td><td>cycle thinking-block visibility</td></tr><tr><td><code>/copy</code></td><td>—</td><td>transcript to clipboard</td></tr><tr><td><code>/export</code></td><td>—</td><td>transcript to file/editor (thinking, tool details, metadata toggles)</td></tr><tr><td><code>/diff</code></td><td>—</td><td>open the diff viewer</td></tr></tbody></table><h2 id="prompt-level" tabindex="-1">Prompt-level <a class="header-anchor" href="#prompt-level" aria-label="Permalink to &quot;Prompt-level&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Does</th></tr></thead><tbody><tr><td><code>/editor</code></td><td>compose next message in <code>$EDITOR</code> (expands pasted-text parts, re-syncs attachments)</td></tr><tr><td><code>/skills</code></td><td>skill picker — inserts <code>/skill-name</code> into the prompt</td></tr><tr><td><code>/warp</code></td><td><em>(experimental)</em> change the session&#39;s workspace</td></tr><tr><td><code>/move</code></td><td>relocate the session to another project directory</td></tr></tbody></table><h2 id="built-ins-server-side-prompt-commands" tabindex="-1">Built-ins (server-side prompt commands) <a class="header-anchor" href="#built-ins-server-side-prompt-commands" aria-label="Permalink to &quot;Built-ins (server-side prompt commands)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Does</th></tr></thead><tbody><tr><td><code>/init</code></td><td>guided AGENTS.md setup — studies the project, writes the context file with you</td></tr><tr><td><code>/review</code></td><td>review changes (commit / branch / PR; default: uncommitted) — runs as a subtask</td></tr></tbody></table><p>Plus anything from your <code>command</code> config / <code>{command,commands}/*.md</code> files (<a href="./../extending/commands.html">custom commands</a>), skill names (see <code>/skills</code>), and remote MCP prompts surfaced as <code>/name:mcp</code>.</p><h2 id="mini-mode" tabindex="-1">Mini mode <a class="header-anchor" href="#mini-mode" aria-label="Permalink to &quot;Mini mode&quot;">​</a></h2><p><code>prioricode --mini</code> ships the minimal set: <code>/editor</code>, <code>/new</code>, <code>/exit</code>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../using/tui.html">Terminal UI</a> — What they feel like in use. <ul><li><a href="./keybinds.html">Keybinds</a> — The non-slash path to the same commands.</li><li><a href="./../extending/commands.html">Custom commands</a> — Add rows to the bottom of this table.</li></ul></li></ul>',14)])])}const u=e(s,[["render",a]]);export{p as __pageData,u as default};
